package day7;
                // signing a contract 
               // override all the methods of animal_ 
public class Tiger implements Animal_ {

	@Override
	public void walk() {
		// TODO Auto-generated method stub
		System.out.println("Tiger walking ");
		
	}

	@Override
	public void dance() {
		// TODO Auto-generated method stub
		System.out.println("Tiger dancing");
		
	}

	@Override
	public void act() {
		// TODO Auto-generated method stub
		System.out.println("Tiger is acting ");
		
	}
	

}


// concrete class -> the class which has implemented all the methods of interface 
// concrete class can be instantiated that means ; we can create objects from the concrete class